def choose_move(observation):
    g = observation.get if isinstance(observation, dict) else (lambda *args, **kwargs: None)

    def to_int(v, default=0):
        try:
            return int(v)
        except Exception:
            return default

    def pt(v, default=(0, 0)):
        if isinstance(v, dict):
            for k in ("position", "pos", "loc", "xy", "coord", "tile", "cell"):
                if k in v:
                    return pt(v.get(k), default)
            x = v.get("x", None)
            y = v.get("y", None)
            if x is not None and y is not None:
                return to_int(x, default[0]), to_int(y, default[1])
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return to_int(v[0], default[0]), to_int(v[1], default[1])
        return default

    w = to_int(g("grid_width", g("width", 0)), 0)
    h = to_int(g("grid_height", g("height", 0)), 0)

    me = pt(g("self_position", g("position", g("agent_position", (0, 0)))))
    opp = pt(g("opponent_position", g("enemy_position", (w - 1, h - 1))))

    obstacles = set()
    for p in g("obstacles", []) or []:
        q = pt(p, None)
        if q is not None:
            obstacles.add(q)

    resources = []
    for p in g("resources", []) or []:
        q = pt(p, None)
        if q is not None:
            resources.append(q)

    targets = []
    for key in ("targets", "goals", "objectives", "territories"):
        for p in g(key, []) or []:
            q = pt(p, None)
            if q is not None:
                targets.append(q)

    def ok(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obstacles

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(points, ref):
        best = None
        bestd = None
        for p in points:
            d = dist(ref, p)
            if best is None or d < bestd:
                best = p
                bestd = d
        return best, bestd if bestd is not None else 10**9

    # Infer mode
    mode = "generic"
    if resources:
        mode = "resource_collection"
    if g("territory", None) is not None or g("control", None) is not None or targets:
        mode = "territory_control"
    if g("lives", None) is not None or g("hp", None) is not None or g("health", None) is not None:
        mode = "pursuit_evasion"

    # Candidate moves: prefer cardinal, then stay
    cands = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]

