                score -= d * 10
            score += 1 if (nx, ny) != opp else -50
            if opp_close:
                score += dist((nx, ny), opp) * 2
            else:
                score -= dist((nx, ny), opp)

        elif mode == "pursuit_evasion":
            # Prefer safety unless we are adjacent and can pressure.
            d_opp = dist((nx, ny), opp)
            score += d_opp * 12
            if d_opp == 0:
                score -= 100
            if opp_close:
                score += 8 if d_opp > dist(me, opp) else -8
            if resources:
                _, d_res = nearest(resources, (nx, ny))
                score -= d_res * 2

        elif mode == "territory_control":
